'use strict';
const $=id=>document.getElementById(id);
let value='',shift=false,numeric=false,compact=false,hand='right',enabled=false,samples=0,switches=0,lastSample=0,peakAt=0,lastPeak=0,cooldown=0,gravity=null;
function renderText(){ $('text').textContent=value; if(!value){const s=document.createElement('span');s.className='placeholder';s.textContent='Your words go here…';$('text').append(s);} $('count').textContent=Array.from(value).length+' characters';$('text').scrollTop=$('text').scrollHeight; }
function layout(){ $('keyboard').style.width=compact?$('width').value+'%':'100%';$('keyboard').style.marginLeft=hand==='right'?'auto':'0';$('keyboard').style.marginRight=hand==='left'?'auto':'0';$('mode').textContent=compact?'Compact · '+hand+' hand':'Full-width mode';$('layoutLabel').textContent=compact?'COMPACT · '+$('width').value+'%':'FULL WIDTH';$('toggle').textContent=compact?'Restore full width ↔':'Try compact ↔';$('hint').textContent=enabled?'Shake to '+(compact?'restore full width':'shrink the keyboard'):'Enable motion, then shake to shrink'; }
function toggle(gesture=false){compact=!compact;layout();if(gesture){switches++;diagnostics();}}
function press(k){if(k==='shift'){shift=!shift;renderKeys();return;}if(k==='123'||k==='ABC'){numeric=!numeric;renderKeys();return;}if(k==='backspace')value=Array.from(value).slice(0,-1).join('');else if(k==='space')value+=' ';else if(k==='enter')value+='\n';else{value+=shift?k.toUpperCase():k;if(shift){shift=false;renderKeys();}}renderText();}
function renderKeys(){const rows=numeric?['1234567890'.split(''),['-','/',':',';','(',')','$','&','@','"'],['shift','.',',','?','!',"'",'backspace'],['ABC','space','enter']]:['qwertyuiop'.split(''),'asdfghjkl'.split(''),['shift',...'zxcvbnm','backspace'],['123',',','space','.','enter']];$('keyboard').replaceChildren();for(const keys of rows){const r=document.createElement('div');r.className='row';for(const k of keys){const b=document.createElement('button');b.type='button';b.className='key'+(['shift','backspace','123','ABC','enter'].includes(k)?' special':'')+(k==='space'?' space':'')+(k==='shift'&&shift?' active':'');b.textContent=({shift:'⇧',backspace:'⌫',space:'space',enter:'return'})[k]||(shift?k.toUpperCase():k);b.setAttribute('aria-label',k);if(k==='shift')b.setAttribute('aria-pressed',String(shift));b.onclick=()=>press(k);r.append(b);}$('keyboard').append(r);}}
function diagnostics(){ $('diagnostics').textContent='Sensor samples: '+samples+' · Gesture switches: '+switches; }
function motion(e){if(!enabled||document.hidden)return;let a=e.acceleration;const now=performance.now();if(!a||![a.x,a.y,a.z].every(Number.isFinite)){const g=e.accelerationIncludingGravity;if(!g||![g.x,g.y,g.z].every(Number.isFinite))return;if(!gravity){gravity={x:g.x,y:g.y,z:g.z};return;}a={};for(const k of ['x','y','z']){gravity[k]=.8*gravity[k]+.2*g[k];a[k]=g[k]-gravity[k];}}
 samples++;lastSample=now;const magnitude=Math.hypot(a.x,a.y,a.z);$('meter').style.width=Math.min(100,magnitude/25*100)+'%';$('motionTitle').textContent='Motion is active';$('motionDot').style.background='#6d9845';$('motionMessage').textContent='Sensor connected. Give your phone a short, gentle shake.';if(samples%10===0||samples===1)diagnostics();if(now<cooldown)return;if(magnitude<Number($('sensitivity').value)*.55){lastPeak=0;return;}if(magnitude>Number($('sensitivity').value)&&!lastPeak){lastPeak=now;if(peakAt&&now-peakAt>80&&now-peakAt<750){toggle(true);cooldown=now+1400;peakAt=0;}else peakAt=now;}}
$('enable').onclick=async()=>{if(enabled){enabled=false;window.removeEventListener('devicemotion',motion);$('enable').textContent='Enable shake ↗';$('motionTitle').textContent='Motion is off';$('motionDot').style.background='#a7afa0';$('motionMessage').textContent='Motion paused. Manual layout controls still work.';$('meter').style.width='0';layout();return;}try{if(!window.isSecureContext)throw new Error('Motion needs HTTPS. Open the published link directly in Safari.');if(typeof DeviceMotionEvent==='undefined')throw new Error('Motion is unavailable here. Open this page on your phone.');if(typeof DeviceMotionEvent.requestPermission==='function'){const p=await DeviceMotionEvent.requestPermission();if(p!=='granted')throw new Error('Motion permission was not granted. Allow motion access in Safari, then retry.');}enabled=true;gravity=null;peakAt=0;lastPeak=0;cooldown=0;lastSample=performance.now();window.addEventListener('devicemotion',motion);$('enable').textContent='Pause motion';$('motionTitle').textContent='Waiting for sensor';$('motionMessage').textContent='Move your phone gently to check the connection.';layout();}catch(e){$('motionTitle').textContent='Motion unavailable';$('motionMessage').textContent=e.message;}};
setInterval(()=>{if(enabled&&!document.hidden&&performance.now()-lastSample>3500){$('motionTitle').textContent='No sensor data yet';$('motionMessage').textContent='Open directly in Safari on your phone and check motion permissions.';}},2000);
for(const side of ['left','right'])$(side).onclick=()=>{hand=side;for(const s of ['left','right'])$(s).setAttribute('aria-pressed',String(s===side));layout();};
$('width').oninput=()=>{$('widthValue').textContent=$('width').value+'%';layout();};$('sensitivity').oninput=()=>{$('sensitivityValue').textContent=Number($('sensitivity').value)<10?'Gentle':Number($('sensitivity').value)>16?'Firm':'Balanced';peakAt=0;};$('toggle').onclick=()=>toggle();$('clear').onclick=()=>{value='';renderText();};
document.addEventListener('keydown',e=>{if(e.target.matches('input,button,summary')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Backspace'){e.preventDefault();press('backspace');}else if(e.key==='Enter'){e.preventDefault();press('enter');}else if(e.key.length===1){e.preventDefault();value+=e.key;renderText();}});
document.addEventListener('visibilitychange',()=>{peakAt=0;lastPeak=0;gravity=null;cooldown=performance.now()+500;});renderKeys();layout();
